<?php
require __DIR__.'/../../config/bootstrap.php';
use Pharmacy\Auth\Authorization;use Pharmacy\Support\Csrf;use Pharmacy\Prescriptions\PrescriptionService;
Authorization::requireRole('ADMIN','PHARMACIST');$message=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{Csrf::validate((string)($_POST['csrf']??''));$items=[];foreach($_POST['medicine_id']??[] as $i=>$mid){if(!(int)$mid)continue;$items[]=['medicine_id'=>(int)$mid,'dosage_instruction'=>trim($_POST['dosage_instruction'][$i]??''),'frequency'=>trim($_POST['frequency'][$i]??''),'duration'=>trim($_POST['duration'][$i]??''),'quantity_prescribed'=>(float)($_POST['quantity_prescribed'][$i]??0)];}$type=$_POST['patient_type']??'EMPLOYEE';$command=['patient_type'=>$type,'employee_id'=>$type==='EMPLOYEE'?(int)($_POST['patient_id']??0):null,'external_patient_id'=>$type==='EXTERNAL'?(int)($_POST['patient_id']??0):null,'doctor_id'=>(int)$_POST['doctor_id'],'visit_date'=>$_POST['visit_date'],'diagnosis_notes'=>trim($_POST['diagnosis_notes']??''),'prescription_notes'=>trim($_POST['prescription_notes']??''),'items'=>$items];$id=(new PrescriptionService($pdo))->create($command,(int)$_SESSION['user']['id']);$message="Prescription #{$id} recorded.";}catch(Throwable $e){$error=$e->getMessage();}}
$employees=$pdo->query("SELECT id,employee_code,name FROM employees WHERE active=1 ORDER BY name LIMIT 1000")->fetchAll();$patients=$pdo->query("SELECT id,patient_code,name FROM external_patients WHERE active=1 ORDER BY name LIMIT 1000")->fetchAll();$doctors=$pdo->query("SELECT id,name,specialization FROM doctors WHERE active=1 ORDER BY name")->fetchAll();$medicines=$pdo->query("SELECT id,name,strength FROM medicines WHERE active=1 ORDER BY name")->fetchAll();$recent=$pdo->query("SELECT p.*,d.name doctor,COALESCE(e.name,x.name) patient_name FROM prescriptions p JOIN doctors d ON d.id=p.doctor_id LEFT JOIN employees e ON e.id=p.employee_id LEFT JOIN external_patients x ON x.id=p.external_patient_id ORDER BY p.id DESC LIMIT 50")->fetchAll();$title='Prescriptions';require __DIR__.'/../../templates/header.php';?>
<h2 class="page-title">Visiting Doctor Prescription</h2><?php if($message):?><div data-flash="<?=htmlspecialchars($message)?>"></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="card mb-4"><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(Csrf::token())?>"><div class="row g-2 mb-3"><div class="col-md-2"><label class="form-label">Patient Type</label><select class="form-select" name="patient_type" id="patientType"><option value="EMPLOYEE">Employee</option><option value="EXTERNAL">External</option></select></div><div class="col-md-4"><label class="form-label">Patient</label><select class="form-select patient-select" name="patient_id" id="employeePatients" required><option value="">Select employee</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=htmlspecialchars($e['employee_code'].' - '.$e['name'])?></option><?php endforeach;?></select><select class="form-select patient-select d-none" id="externalPatients"><option value="">Select external patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['patient_code'].' - '.$p['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Visiting Doctor</label><select class="form-select" name="doctor_id" required><option value="">Select doctor</option><?php foreach($doctors as $d):?><option value="<?=$d['id']?>"><?=htmlspecialchars($d['name'].' '.$d['specialization'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Visit Date</label><input class="form-control" type="date" name="visit_date" value="<?=date('Y-m-d')?>" required></div></div><div class="mb-3"><label class="form-label">Diagnosis / Complaint</label><textarea class="form-control" name="diagnosis_notes"></textarea></div><div class="table-responsive"><table class="table" id="rxItems"><thead><tr><th>Medicine</th><th>Dosage</th><th>Frequency</th><th>Duration</th><th>Qty</th><th></th></tr></thead><tbody><tr class="rx-row"><td><select class="form-select" name="medicine_id[]" required><option value="">Select</option><?php foreach($medicines as $m):?><option value="<?=$m['id']?>"><?=htmlspecialchars($m['name'].' '.$m['strength'])?></option><?php endforeach;?></select></td><td><input class="form-control" name="dosage_instruction[]" placeholder="e.g. after food"></td><td><input class="form-control" name="frequency[]" placeholder="1-0-1"></td><td><input class="form-control" name="duration[]" placeholder="5 days"></td><td><input class="form-control" type="number" step="0.001" min="0.001" name="quantity_prescribed[]" required></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-rx">×</button></td></tr></tbody></table></div><button type="button" class="btn btn-outline-secondary" id="addRx">Add Medicine</button> <button class="btn btn-dark">Save Prescription</button></form></div></div>
<div class="card"><div class="card-body"><h5>Recent Prescriptions</h5><table class="table datatable"><thead><tr><th>No.</th><th>Date</th><th>Patient</th><th>Doctor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=htmlspecialchars($r['prescription_no'])?></td><td><?=$r['visit_date']?></td><td><?=htmlspecialchars($r['patient_name'])?></td><td><?=htmlspecialchars($r['doctor'])?></td><td><?=$r['status']?></td><td><a class="btn btn-sm btn-dark" href="/dispensing/index.php?prescription_id=<?=$r['id']?>">Dispense</a></td></tr><?php endforeach;?></tbody></table></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const type=document.querySelector('#patientType'),emp=document.querySelector('#employeePatients'),ext=document.querySelector('#externalPatients');type.onchange=()=>{const external=type.value==='EXTERNAL';emp.classList.toggle('d-none',external);ext.classList.toggle('d-none',!external);emp.name=external?'':'patient_id';ext.name=external?'patient_id':''};const body=document.querySelector('#rxItems tbody');document.querySelector('#addRx').onclick=()=>{const r=body.querySelector('.rx-row').cloneNode(true);r.querySelectorAll('input').forEach(i=>i.value='');r.querySelector('select').value='';body.appendChild(r)};body.addEventListener('click',e=>{if(e.target.classList.contains('remove-rx')&&body.children.length>1)e.target.closest('tr').remove()})});</script>
<?php require __DIR__.'/../../templates/footer.php';
